CREATE TYPE "HermesRuntimeStatus" AS ENUM ('ACTIVE', 'PAUSED', 'ARCHIVED');
CREATE TYPE "HermesExecutionStatus" AS ENUM ('QUEUED', 'DISPATCHING', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED');
ALTER TYPE "TaskActivityType" ADD VALUE 'RUNTIME_QUEUED';
