ALTER TYPE "TaskActivityType" ADD VALUE 'RUNTIME_FAILED';
CREATE TABLE "HermesRuntime" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "status" "HermesRuntimeStatus" NOT NULL DEFAULT 'ACTIVE', "endpoint" TEXT, "profileKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HermesRuntime_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HermesRuntimeAssignment" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "runtimeId" TEXT NOT NULL, "employeeProjectAssignmentId" TEXT, "profileKey" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HermesRuntimeAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HermesExecution" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "taskId" TEXT NOT NULL, "runtimeId" TEXT NOT NULL, "runtimeAssignmentId" TEXT NOT NULL, "status" "HermesExecutionStatus" NOT NULL DEFAULT 'QUEUED', "prompt" TEXT NOT NULL, "resultText" TEXT, "errorMessage" TEXT, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "HermesExecution_pkey" PRIMARY KEY ("id"));
